def get_skill_name(skill_id: int) -> str:
    if skill_id in SKILLS:
        return SKILLS[skill_id][0]
    return str(skill_id)

def get_skill_group(skill_id: int) -> str | None:
    if skill_id in SKILLS:
        return SKILLS[skill_id][1]
    return None

def get_skill_category(skill_id: int) -> str | None:
    if skill_id in SKILLS:
        return SKILLS[skill_id][2]
    return None

def is_unknown_skill(skill_id: int) -> bool:
    """Returns True if the skill ID is not in our database or has ID as name."""
    if skill_id not in SKILLS:
        return True
    name, group, cat = SKILLS[skill_id]
    return name == str(skill_id) or (group == "Unknown" and cat == "Other")
